use std::collections::HashSet;

fn has_common_element(a: &[i32], b: &[i32]) -> bool {
    // If either slice is empty, there can't be any common elements
    if a.is_empty() || b.is_empty() {
        return false;
    }
    
    // Create a HashSet from the first slice for O(1) lookups
    let set_a: HashSet<i32> = a.iter().copied().collect();
    
    // Check if any element from b exists in the set
    b.iter().any(|&x| set_a.contains(&x))
}

fn slice_contains(s: &[i32], val: i32) -> bool {
    // Linear search through the slice
    s.iter().any(|&x| x == val)
}